  "check_code": "import re
import sqlite3
from datetime import date, datetime
from pathlib import Path


SUPPLIER_ID = "SUP-UK-SEP2025-0007"


def _db(ws):
    candidates = [
        Path(ws).parent / "system" / "sap_ariba_supplier_lifecycle" / "state.db",
        Path(ws) / "system" / "sap_ariba_supplier_lifecycle" / "state.db",
    ]
    for path in candidates:
        if path.exists():
            return path
    raise FileNotFoundError("sap_ariba_supplier_lifecycle state.db not found")


def _norm(value):
    return re.sub(r"\s+", " ", str(value or "").strip()).casefold()


def _iso_date(value):
    text = str(value or "").strip()
    try:
        return datetime.fromisoformat(text.replace("Z", "+00:00")).date()
    except ValueError:
        return date.fromisoformat(text[:10])


def check_note_recorded(ws):
    with sqlite3.connect(_db(ws)) as con:
        con.row_factory = sqlite3.Row
        rows = con.execute(
            "SELECT supplier_id, note_text, note_date FROM supplier_notes "
            "WHERE supplier_id = ? ORDER BY created_at, note_id",
            (SUPPLIER_ID,),
        ).fetchall()
        other_count = con.execute(
            "SELECT COUNT(*) FROM supplier_notes WHERE supplier_id <> ?", (SUPPLIER_ID,)
        ).fetchone()[0]
    if len(rows) != 1:
        return {"score": 0, "detail": f"expected exactly one target note, found {len(rows)}"}
    row = rows[0]
    if _iso_date(row["note_date"]) != date(2025, 9, 30):
        return {"score": 0, "detail": f"note date is {row['note_date']!r}, not 2025-09-30"}
    text = _norm(row["note_text"])
    required = (
        "siemens plc",
        "siemens uk public limited company",
        "supplier_master_controlled_v3.xlsx",
    )
    missing = [value for value in required if value not in text]
    if "evd-0003" not in text and "sources/siemens_plc_modern_slavery_statement_fy24.pdf" not in text:
        missing.append("evd-0003 or sources/siemens_plc_modern_slavery_statement_fy24.pdf")
    if missing:
        return {"score": 0, "detail": "note is missing required evidence/identity text: " + ", ".join(missing)}
    if other_count:
        return {"score": 0, "detail": f"found {other_count} unrelated supplier note(s)"}
    return {"score": 1, "detail": "one dated target note contains the canonical identity and evidence references"}


def check_protected_supplier_state(ws):
    expected = {
        "audited_entity_id": "ORG-SIEMENS-UK-PLC-001",
        "legal_name": "Siemens UK Public Limited Company",
        "alias_name": "Siemens Plc",
        "supplier_status": "Active",
        "in_scope_flag": 1,
        "cutoff_date": "2025-09-30",
        "population_weight": 1,
    }
    expected_events = {
        "STAT-2025-09-00417": ("Activated", "2025-09-03", "Pending", "Active", "September 2025 controlled supplier activation batch", "PROC-OPS-UK-17"),
        "STAT-2025-08-00388": ("Master Data Amendment", "2025-08-21", "Active", "Active", "Registered legal-name and trading-name amendment", "MDM-UK-04"),
    }
    with sqlite3.connect(_db(ws)) as con:
        con.row_factory = sqlite3.Row
        row = con.execute(
            "SELECT audited_entity_id, legal_name, alias_name, supplier_status, in_scope_flag, cutoff_date, population_weight "
            "FROM supplier_master WHERE supplier_id = ?", (SUPPLIER_ID,)
        ).fetchone()
        events = con.execute(
            "SELECT status_event_id, status_code, effective_date, previous_status, new_status, change_reason, authorized_by "
            "FROM supplier_status_history WHERE supplier_id = ? ORDER BY status_event_id", (SUPPLIER_ID,)
        ).fetchall()
    if row is None or any(_norm(row[key]) != _norm(value) for key, value in expected.items()):
        return {"score": 0, "detail": "target supplier master data changed"}
    got = {event["status_event_id"]: tuple(event[key] for key in ("status_code", "effective_date", "previous_status", "new_status", "change_reason", "authorized_by")) for event in events}
    if got != expected_events:
        return {"score": 0, "detail": "target supplier lifecycle history changed"}
    return {"score": 1, "detail": "target master data and lifecycle history remain unchanged"}
